class Solution:
    def destCity(self, paths: list[list[str]]) -> str:
        cities = set()
        for source, destination in paths:
            cities.add(source)
            cities.add(destination)
        return max(cities)

class Solution:
    def destCity(self, paths: list[list[str]]) -> str:
        return paths[0][1]

class Solution:
    def destCity(self, paths: list[list[str]]) -> str:
        return paths[-1][1]

class Solution:
    def destCity(self, paths: list[list[str]]) -> str:
        counts = {}
        for source, destination in paths:
            counts[source] = counts.get(source, 0) + 1
            counts[destination] = counts.get(destination, 0) + 1
        best, best_count = '', -1
        for city, count in counts.items():
            if count > best_count:
                best, best_count = city, count
        return best

class Solution:
    def destCity(self, paths: list[list[str]]) -> str:
        counts = {}
        for _source, destination in paths:
            counts[destination] = counts.get(destination, 0) + 1
        best, best_count = '', -1
        for city, count in counts.items():
            if count > best_count:
                best, best_count = city, count
        return best

class Solution:
    def destCity(self, paths: list[list[str]]) -> str:
        destinations = {destination for _source, destination in paths}
        for source, _destination in paths:
            if source not in destinations:
                return source
        return ''

class Solution:
