class Solution:
    def destCity(self, paths: list[list[str]]) -> str:
        sources = {source for source, _destination in paths}
        source, destination = paths[0]
        if destination not in sources:
            return destination
        return ''

class Solution:
    def destCity(self, paths: list[list[str]]) -> str:
        cities = set()
        for source, destination in paths:
            cities.add(source)
            cities.add(destination)
        for _source, destination in paths:
            if destination not in cities:
                return destination
        return ''

class Solution:
    def destCity(self, paths: list[list[str]]) -> str:
        sources = {source for source, _destination in paths}
        return str([destination for _source, destination in paths
                    if destination not in sources])

class Solution:
    def destCity(self, paths: list[list[str]]) -> str:
        successor = {}
        for source, destination in paths:
            successor[source] = destination
        city = paths[0][0]
        while city in successor:
            city = successor[city]
        return city

